// One request, one verified caller company. Never interpolate unchecked Drive query values.
if ($input.all().length !== 1) throw new Error('Exactly one provisioning request is required');
const body = $input.first().json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Invalid request body');
for (const field of ['brandName','clientEmail','company_id','planner_kind','templateSheetId']) {
  if (typeof body[field] !== 'string' || !body[field].trim()) throw new Error('missing required field: '+field);
}
for (const field of ['company_id','planner_kind','templateSheetId']) {
  if (!/^[A-Za-z0-9_-]+$/.test(body[field])) throw new Error('Invalid identity: '+field);
}
const provisioningKey = body.company_id+'::'+body.planner_kind;
// Google Drive property key + value is limited to 124 bytes.
if (provisioningKey.length + 'skill35_provisioning_key'.length > 124) throw new Error('Provisioning identity is too long');
const timezone=body.timezone || 'UTC';
new Intl.DateTimeFormat('en-US',{timeZone:timezone}).format();
return [{json:{...body,body,timezone,provisioningKey,
  sheetName:body.brandName.trim()+' Social Media Planner',
  readbackQuery:"appProperties has { key='skill35_provisioning_key' and value='"+provisioningKey+"' } and trashed = false"}}];

// F14 — classify the template verification result BEFORE provisioning.
// Same credential class (googleDriveOAuth2Api) the copy uses, so the status is
// authoritative for the copy path:
//   404 => 'template_not_found'    — the templateSheetId is wrong or deleted
//          (identity repair: correct the registered template ID; NEVER make a
//          replacement template or an ad-hoc sheet as a side effect).
//   403 => 'template_access_denied' — the operator credential lost access to
//          the template (access repair: re-grant access to the EXISTING file).
//   other => 'transient' — bounded retries (3x/2s) already applied; surfaced so
//          the caller retries provisioning without losing the pending marker.
const src = $('Validate + Build Provisioning Key').first().json;
const err = $input.first().json;
const e=typeof err.error==='object' ? err.error : err; const status=Number(e.httpCode || e.statusCode || e.status || e.response?.statusCode || e.response?.status || err.statusCode || err.response?.statusCode || err.response?.status);
let repair_state = 'transient';
let repair_action = 'Transient Google Drive error after 3 bounded retries — provisioning stays pending; retry the create with the SAME provisioning key (the readback dedupes).';
if (status === 404) {
  repair_state = 'template_not_found';
  repair_action = 'The template sheet ID ' + src.templateSheetId + ' does not exist or was deleted. Identity repair: correct the registered templateSheetId — do NOT provision a replacement sheet from another source silently; the pending marker reconciles once the ID is verified.';
} else if (status === 403) {
  repair_state = 'template_access_denied';
  repair_action = 'The operator Drive credential is denied access to the template ' + src.templateSheetId + '. Access repair: re-grant the operator credential access to the EXISTING template, then retry provisioning with the SAME provisioning key.';
}
return [{ json: {
  status: 'error',
  repair_required: true,
  repair_state: repair_state,
  repair_action: repair_action,
  provisioning_key: src.provisioningKey
} }];

const src=$('Validate + Build Provisioning Key').first().json;
const response=$input.first().json;
if (!Array.isArray(response.files)) throw new Error('Malformed Drive readback');
if (response.nextPageToken || response.files.length>1) throw new Error('Ambiguous provisioning identity; reconcile registry before retry');
const existingFile=response.files[0] || null;
if (existingFile) {
  const p=existingFile.appProperties || {};
  if (!existingFile.id || p.skill35_company_id!==src.company_id || p.skill35_provisioning_key!==src.provisioningKey)
    throw new Error('Existing planner ownership is unverified; migrate from verified registry before retry');
  if (!['initializing','formatted','ready'].includes(p.skill35_provisioning_state)) throw new Error('Existing planner state requires verified migration');
  if (p.skill35_template_schema!=='1.2.0') throw new Error('Existing planner schema requires a preserving migration');
}
return [{json:{...src,existing:!!existingFile,existingFile}}];

const SCHEMA={"tabs":{"Weekly Overview":{"frozen_columns":0,"headings":["Week Of","Theme of the Week","Research","Core Content","Images","Videos","Facebook","Instagram","LinkedIn","YouTube","TikTok","Pinterest","Carousels","Blog","Podcast","Email","QC","Scheduled","Overall","Notes"],"status_columns":["QC","Overall"]},"This Week":{"headings":["Week","Client","Next Action","Drafting","QC","Scheduled","Published","Needs Attention"]},"Posts":{"frozen_columns":2,"headings":["row_key","company_id","cycle_id","content_revision","account_id","platform","account_name","format","scheduled_local","scheduled_utc","state","qc_state","preview_url","remote_url"],"status_columns":["state","qc_state"]},"Images":{"headings":["asset_key","content_id","asset_id","company_id","cycle_id","content_revision","kind","preview_url","original_url","ratio","width","height","alt_text","qc_state"]},"Videos":{"headings":["video_key","content_id","asset_id","company_id","cycle_id","content_revision","version","poster_url","published_url","watch_url","duration_seconds","ratio","captions","qc_state"]}},"status_colors":{"description":"F25 \u2014 every status value gets BOTH a TEXT_EQ conditional format rule (never NUMBER_EQ: statuses are text) and a written label, so color is never the only signal. Dropdowns are enforced with setDataValidation on the same value list.","statuses":[{"label":"Complete","color":"#b7e1cd","color_label":"green \u2014 done"},{"label":"Failed","color":"#f4c7c3","color_label":"red \u2014 needs repair"},{"label":"QC Review","color":"#fce8b2","color_label":"amber \u2014 in review"},{"label":"Scheduled","color":"#d3e3fd","color_label":"blue \u2014 queued for posting"},{"label":"Published","color":"#c9daf8","color_label":"blue \u2014 live on platform"},{"label":"Needs Attention","color":"#f6aea9","color_label":"red \u2014 blocking issue"}]}};
// Run ONLY on a privately initializing copy, never a ready client planner.
const ctx=$('Sheet Context').first().json;
if(ctx.formatted) throw new Error('Refusing to reset an existing ready planner');
const metadata=$input.first().json;
const templates=SCHEMA.tabs;
const current=metadata.sheets || [];
const ids=new Set(current.map(s=>s.properties.sheetId));
const byTitle=Object.fromEntries(current.map(s=>[s.properties.title,s]));
const numeric={}; const newSheetRequests=[]; const formatRequests=[];
const order=['This Week','Weekly Overview','Posts','Images','Videos'];
let nextId=1;
for(const title of order){
  const existing=byTitle[title];
  while(ids.has(nextId))nextId++;
  const id=existing ? existing.properties.sheetId : nextId++;
  ids.add(id); numeric[title]=id;
  const columns=title==='Images'?16:title==='Videos'?19:title==='Weekly Overview'?21:templates[title].headings.length;
  if(!existing)newSheetRequests.push({addSheet:{properties:{sheetId:id,title,gridProperties:{rowCount:1000,columnCount:columns}}}});
  const grid=existing?.properties.gridProperties || {};
  formatRequests.push({updateSheetProperties:{properties:{sheetId:id,index:order.indexOf(title),gridProperties:{frozenRowCount:1,frozenColumnCount:templates[title].frozen_columns||0,rowCount:Math.max(grid.rowCount||0,1000),columnCount:Math.max(grid.columnCount||0,columns)}},fields:'index,gridProperties'}});
  // Copied merged title cells can silently hide all but the first header.
  formatRequests.push({unmergeCells:{range:{sheetId:id}}});
  // Template content (including sample publication claims) is never client content.
  formatRequests.push({updateCells:{range:{sheetId:id},fields:'userEnteredValue,note,dataValidation'}});
  for(let i=(existing?.conditionalFormats||[]).length-1;i>=0;i--)formatRequests.push({deleteConditionalFormatRule:{sheetId:id,index:i}});
  const headings=[...templates[title].headings];
  if(title==='Weekly Overview')headings[20]='cycle_id';
  if(title==='Images')headings[15]='Image preview';
  if(title==='Videos'){headings[17]='Video poster';headings[18]='Watch video';}
  formatRequests.push({updateCells:{start:{sheetId:id,rowIndex:0,columnIndex:0},rows:[{values:Array.from(headings,h=>({userEnteredValue:{stringValue:h||''}}))}],fields:'userEnteredValue'}});
  formatRequests.push({repeatCell:{range:{sheetId:id},cell:{userEnteredFormat:{wrapStrategy:'WRAP',verticalAlignment:'TOP'}},fields:'userEnteredFormat.wrapStrategy,userEnteredFormat.verticalAlignment'}});
  formatRequests.push({repeatCell:{range:{sheetId:id,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{backgroundColor:{red:.10,green:.16,blue:.25},textFormat:{bold:true,foregroundColor:{red:1,green:1,blue:1}}}},fields:'userEnteredFormat.backgroundColor,userEnteredFormat.textFormat'}});
  formatRequests.push({updateDimensionProperties:{range:{sheetId:id,dimension:'ROWS',startIndex:0,endIndex:1},properties:{pixelSize:44},fields:'pixelSize'}});
  formatRequests.push({updateDimensionProperties:{range:{sheetId:id,dimension:'COLUMNS',startIndex:0,endIndex:columns},properties:{pixelSize:170},fields:'pixelSize'}});
  // Strict dropdowns apply only to status cells, never captions, dates or URLs.
  for(const column of templates[title].status_columns || []){
    // QC overview is a multi-account textual aggregate, not an enum.
    if(title==='Weekly Overview' && column==='QC')continue;
    const col=templates[title].headings.indexOf(column);
    const range={sheetId:id,startRowIndex:1,startColumnIndex:col,endColumnIndex:col+1};
    const statusValues=SCHEMA.status_colors.statuses.map(s=>s.label);
    const runtime=['PASS','FAIL','PENDING','IN_REVIEW','SKIP','draft','drafting','pending','queued','working','qc_pending','qc_review','approved','passed','rejected','scheduled','published','failed','blocked','needs_attention','skipped','complete','completed','cancelled'];
    const labels=[...new Set([...statusValues,...runtime])];
    formatRequests.push({setDataValidation:{range,rule:{condition:{type:'ONE_OF_LIST',values:labels.map(s=>({userEnteredValue:s}))},showCustomUi:true,strict:true}}});
    for(const label of labels){
      const st=SCHEMA.status_colors.statuses.find(s=>s.label.toLowerCase()===label.toLowerCase()) || SCHEMA.status_colors.statuses[2];
      const hex=st.color.slice(1);const color={red:parseInt(hex.slice(0,2),16)/255,green:parseInt(hex.slice(2,4),16)/255,blue:parseInt(hex.slice(4,6),16)/255};
      formatRequests.push({addConditionalFormatRule:{rule:{ranges:[range],booleanRule:{condition:{type:'TEXT_EQ',values:[{userEnteredValue:label}]},format:{backgroundColor:color}}},index:0}});
    }
  }
  const formulaCols=title==='Images'?[15]:title==='Videos'?[17,18]:title==='This Week'?[0,2,3,4,5,6,7]:[];
  for(const col of formulaCols){
    const description='skill35 trusted formula '+title+' '+col;
    if(!(existing?.protectedRanges||[]).some(r=>r.description===description))formatRequests.push({addProtectedRange:{protectedRange:{description,range:{sheetId:id,startRowIndex:1,startColumnIndex:col,endColumnIndex:col+1},warningOnly:false}}});
  }
  if(title==='Images' || title==='Videos'){
    const col=title==='Images'?15:17;
    formatRequests.push({updateDimensionProperties:{range:{sheetId:id,dimension:'COLUMNS',startIndex:col,endIndex:col+1},properties:{pixelSize:title==='Images'?220:240},fields:'pixelSize'}});
  }
}
for(const sheet of current){
  if(!order.includes(sheet.properties.title))formatRequests.push({deleteSheet:{sheetId:sheet.properties.sheetId}});
}
formatRequests.push({updateSpreadsheetProperties:{properties:{title:ctx.sheetName,timeZone:ctx.timezone},fields:'title,timeZone'}});
// Required for IMAGE previews; set only while false (true is read-only).
if(metadata.properties?.importFunctionsExternalUrlAccessAllowed!==true)formatRequests.push({updateSpreadsheetProperties:{properties:{importFunctionsExternalUrlAccessAllowed:true},fields:'importFunctionsExternalUrlAccessAllowed'}});
for(const [key,value] of Object.entries({skill35_company_id:ctx.company_id,skill35_planner_kind:ctx.planner_kind,skill35_template_schema:'1.2.0'})){
  const entries=(metadata.developerMetadata||[]).filter(m=>m.metadataKey===key);
  for(const entry of entries)formatRequests.push({deleteDeveloperMetadata:{dataFilter:{developerMetadataLookup:{metadataId:entry.metadataId}}}});
  formatRequests.push({createDeveloperMetadata:{developerMetadata:{metadataKey:key,metadataValue:value,location:{spreadsheet:true},visibility:'DOCUMENT'}}});
}
return [{json:{newSheetRequests,formatRequests,numeric,statuses:SCHEMA.status_colors.statuses.map(s=>s.label)}}];

const numeric=$('Build Formatting Requests (F25)').first().json.numeric;
const ctx=$('Sheet Context').first().json;
const id=numeric['This Week'];
const identityStamps=[];
[110,190,300,130,130,130,130,160].forEach((pixelSize,i)=>identityStamps.push({updateDimensionProperties:{range:{sheetId:id,dimension:'COLUMNS',startIndex:i,endIndex:i+1},properties:{pixelSize},fields:'pixelSize'}}));
// Summary is restricted to the current local week; no invented completion counts.
const week='=TODAY()-WEEKDAY(TODAY(),2)+1';
const count=(field,state)=>`SUMPRODUCT((LOWER(Posts!${field}:${field})="${state.toLowerCase()}")*(LEFT(Posts!I:I,10)>=TEXT(A2,"yyyy-mm-dd"))*(LEFT(Posts!I:I,10)<TEXT(A2+7,"yyyy-mm-dd")))`;

const attentionStates=[['K','failed'],['K','blocked'],['K','needs_attention'],['K','needs attention'],['L','fail'],['L','failed'],['L','rejected']];
const attention='SUMPRODUCT((('+attentionStates.map(([c,s])=>'(LOWER(Posts!'+c+':'+c+')="'+s+'")').join('+')+')>0)*(LEFT(Posts!I:I,10)>=TEXT(A2,"yyyy-mm-dd"))*(LEFT(Posts!I:I,10)<TEXT(A2+7,"yyyy-mm-dd")))';
const values=[{formulaValue:week},{stringValue:ctx.brandName},{formulaValue:'=IF(H2>0,"Review items needing attention",IF(SUM(D2:G2)=0,"Choose this week’s theme","Review progress and approvals"))'},
 {formulaValue:'='+count('K','draft')+'+'+count('K','drafting')},
 {formulaValue:'='+count('L','qc_pending')+'+'+count('L','qc_review')+'+'+count('L','QC Review')+'+'+count('L','pending')+'+'+count('L','in_review')},
 {formulaValue:'='+count('K','scheduled')},{formulaValue:'='+count('K','published')},
 {formulaValue:'='+attention}];
identityStamps.push({updateCells:{start:{sheetId:id,rowIndex:1,columnIndex:0},rows:[{values:values.map(userEnteredValue=>({userEnteredValue}))}],fields:'userEnteredValue'}});
identityStamps.push({repeatCell:{range:{sheetId:id,startRowIndex:1,endRowIndex:2,startColumnIndex:0,endColumnIndex:1},cell:{userEnteredFormat:{numberFormat:{type:'DATE',pattern:'mmm d, yyyy'}}},fields:'userEnteredFormat.numberFormat'}});
return [{json:{identityStamps,thisWeekCreated:true}}];

const src=$('Interpret Readback').first().json;
const file=src.existing ? src.existingFile : $input.first().json;
const p=file.appProperties || {};
if (typeof file.id!=='string' || !/^[A-Za-z0-9_-]+$/.test(file.id) || p.skill35_company_id!==src.company_id || p.skill35_provisioning_key!==src.provisioningKey)
  throw new Error('Drive copy/readback did not prove this company owns the planner');
return [{json:{...src,sheetId:file.id,sheetName:file.name || src.sheetName,deduped:src.existing,
  ready:p.skill35_provisioning_state==='ready',formatted:['formatted','ready'].includes(p.skill35_provisioning_state)}}];

const ctx=$('Sheet Context').first().json;const meta=$input.first().json;
if(meta.spreadsheetId!==ctx.sheetId || !Array.isArray(meta.sheets))throw new Error('Sheet metadata readback failed');
const expected={skill35_company_id:ctx.company_id,skill35_planner_kind:ctx.planner_kind,skill35_template_schema:'1.2.0'};
for(const [key,value] of Object.entries(expected)){
 const entries=(meta.developerMetadata||[]).filter(x=>x.metadataKey===key);
 if(entries.some(x=>x.metadataValue!==value) || (ctx.formatted && entries.length!==1))throw new Error('Sheet ownership/schema missing or mismatched; verified migration required');
}
if(ctx.formatted)for(const title of ['This Week','Weekly Overview','Posts','Images','Videos'])if(!meta.sheets.some(x=>x.properties.title===title))throw new Error('Existing planner missing required tab '+title+'; preserving structural repair required');
return [{json:{...meta,ready:ctx.formatted}}];
